package solution

import (
	"bytes"
	"errors"
	"reflect"
	"testing"
)

func TestParseBadgeValidAndDuplicateFields(t *testing.T) {
	data := []byte(" \n {\"label\":\"  Core Contributor  \",\"level\":\"gold\",\"label\":\"  Final Label \"} \t")
	before := append([]byte(nil), data...)
	allowed := []string{"bronze", "gold", "silver"}
	allowedBefore := append([]string(nil), allowed...)

	got, err := ParseBadge(data, allowed)
	if err != nil {
		t.Fatalf("ParseBadge returned error: %v", err)
	}
	want := Badge{Label: "Final Label", Level: "gold"}
	if got != want {
		t.Fatalf("ParseBadge = %#v, want %#v", got, want)
	}
	if !bytes.Equal(data, before) {
		t.Fatal("ParseBadge mutated data")
	}
	if !reflect.DeepEqual(allowed, allowedBefore) {
		t.Fatal("ParseBadge mutated allowedLevels")
	}
}

func TestParseBadgeLevelMatchingIsExact(t *testing.T) {
	for _, data := range [][]byte{
		[]byte(`{"label":"badge","level":"Gold"}`),
		[]byte(`{"label":"badge","level":" gold"}`),
		[]byte(`{"label":"badge","level":"gold "}`),
	} {
		got, err := ParseBadge(data, []string{"gold"})
		if got != (Badge{}) || !errors.Is(err, ErrInvalidBadge) {
			t.Fatalf("ParseBadge(%s) = (%#v, %v), want zero badge and ErrInvalidBadge", data, got, err)
		}
	}

	got, err := ParseBadge([]byte(`{"label":"x","level":""}`), []string{""})
	if err != nil || got != (Badge{Label: "x", Level: ""}) {
		t.Fatalf("explicitly allowed empty level = (%#v, %v)", got, err)
	}
}

func TestParseBadgeInvalidBadge(t *testing.T) {
	cases := [][]byte{
		[]byte(`{"label":"","level":"gold"}`),
		[]byte(`{"label":" \t\n ","level":"gold"}`),
		[]byte(`{"level":"gold"}`),
		[]byte(`{"label":"valid","level":"missing"}`),
	}
	for _, data := range cases {
		got, err := ParseBadge(data, []string{"gold"})
		if got != (Badge{}) || !errors.Is(err, ErrInvalidBadge) {
			t.Errorf("ParseBadge(%s) = (%#v, %v), want zero badge and ErrInvalidBadge", data, got, err)
		}
	}
}

func TestParseBadgeMalformedInput(t *testing.T) {
	cases := [][]byte{
		nil,
		[]byte("   \n\t"),
		[]byte(`{"label":"x","level":"gold"`),
		[]byte(`[]`),
		[]byte(`{"label":"x","level":"gold","extra":1}`),
		[]byte(`{"label":"x","level":"gold"} {}`),
		[]byte(`{"label":1,"level":"gold"}`),
	}
	for _, data := range cases {
		got, err := ParseBadge(data, []string{"gold"})
		if got != (Badge{}) || !errors.Is(err, ErrMalformedBadge) {
			t.Errorf("ParseBadge(%q) = (%#v, %v), want zero badge and ErrMalformedBadge", data, got, err)
		}
	}
}

