package solution

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
)

type Badge struct {
	Label string `json:"label"`
	Level string `json:"level"`
}

var ErrMalformedBadge = errors.New("malformed badge")
var ErrInvalidBadge = errors.New("invalid badge")

func ParseBadge(data []byte, allowedLevels []string) (Badge, error) {
	var badge Badge
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&badge); err != nil {
		return Badge{}, fmt.Errorf("%w: %v", ErrMalformedBadge, err)
	}
	badge.Label = strings.TrimSpace(badge.Label)
	if badge.Label == "" {
		return Badge{}, fmt.Errorf("%w: blank label", ErrInvalidBadge)
	}
	allowed := false
	for _, level := range allowedLevels {
		if badge.Level == level {
			allowed = true
			break
		}
	}
	if !allowed {
		return Badge{}, fmt.Errorf("%w: unsupported level", ErrInvalidBadge)
	}
	return badge, nil
}

